const toastEl=document.getElementById('toast'),dialogEl=document.getElementById('dialog');let toastTimer,tonics=2;
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2500)}
function openDialog(title,body,button='CONTINUE',cb=null){dialogue=true;document.getElementById('dtitle').textContent=title;document.getElementById('dbody').textContent=body;let b=document.getElementById('daction');b.textContent=button;b.onclick=()=>{dialogEl.classList.remove('show');dialogue=false;if(cb)cb()};dialogEl.classList.add('show')}
function near(kind){let o=objects.find(o=>o.kind===kind);return o&&Math.hypot(o.x-player.x,o.z-player.z)<1.9?o:null}
function interact(){if(!started)return;let npc=near('npc'),bell=near('bell'),shrine=near('shrine');if(npc&&quest===0){openDialog('Tomas, the bellkeeper','I thought the valley had forgotten me. The old bell is still standing by the broken arch — ring it, and the ward will wake. I will follow when the path is safe.','TAKE THE QUEST',()=>{quest=1;document.getElementById('questTitle').textContent='Wake the Valley Ward';document.getElementById('questText').textContent='Find the bell beside the old stone arch.';toast('Quest updated · Wake the Valley Ward')});return}if(npc&&quest>0){openDialog('Tomas, the bellkeeper',quest===1?'The bell remembers a time before roads. Give it a voice, Elara.':'I can hear the green in the stones again. We might have a future after all.');return}if(bell&&quest===1){collected.add('bell');quest=2;xp+=80;document.getElementById('questTitle').textContent='A Light in the Roots';document.getElementById('questText').textContent='Carry the bell’s echo to the moss-covered shrine.';openDialog('The bell answers','Its clear note rolls through the valley. Far away, something old stirs beneath the moss. +80 XP','CONTINUE',()=>toast('Quest updated · A Light in the Roots'));return}if(shrine&&quest===2){quest=3;xp+=160;coins+=20;document.querySelector('.level b').textContent=`✦ ${xp} / 600 XP`;document.querySelector('.level span:last-child').textContent=`◈ ${coins}`;document.getElementById('questTitle').textContent='The Valley Remembers';document.getElementById('questText').textContent='The ward is awake. Explore the Greenward and make it your own.';openDialog('The Greenward stirs','A soft green light rises from the roots. The valley knows your name again. You found your first ward. +160 XP · +20 crowns','WANDER ON',()=>toast('Quest complete · The Valley Remembers'));return}if(near('crystal')){coins+=4;document.querySelector('.level span:last-child').textContent=`◈ ${coins}`;let cr=objects.find(o=>o.kind==='crystal');if(cr)objects.splice(objects.indexOf(cr),1);toast('Moonstone collected · +4 crowns');return}toast('Nothing nearby answers your call.')}
function strike(){if(!started||dialogue||player.attack>0)return;player.attack=.38;st=Math.max(0,st-5);let deer=objects.find(o=>o.kind==='deer'&&Math.hypot(o.x-player.x,o.z-player.z)<2.5);if(deer){toast('The deer slips into the brush. Some things are better left unharmed.');deer.x+=3;deer.z-=2}}
